import com.alibaba.druid.sql.parser.SQLParserUtils;
import com.alibaba.druid.DbType;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;
public class Split2 {
  static void run(String label, String sql, DbType t, boolean cleanFirst) {
    String s = cleanFirst ? SQLParserUtils.removeComment(sql, t) : sql;
    List<String> parts;
