      String p=parts.get(i).trim();
      if (p.length()<50) System.out.println("  short["+i+"]="+p);
      else System.out.println("  ["+i+"] len="+p.length()+" head="+p.substring(0,Math.min(60,p.length())).replace("\n"," "));
    }
  }
  public static void main(String[] args) throws Exception {
    String sql = Files.readString(Path.of("/tmp/drama_rank_sql.sql"));
    run("other+clean", sql, DbType.other, true);
