def req(method, url, data=None, form=False, timeout=180):
    headers={"token": token}
    body=None
    if data is not None:
        body=urllib.parse.urlencode(data).encode() if form else json.dumps(data).encode()
        headers["Content-Type"]="application/x-www-form-urlencoded" if form else "application/json"
    r=urllib.request.Request(base+url, data=body, headers=headers, method=method)
    with urllib.request.urlopen(r, timeout=timeout) as resp:
        return json.loads(resp.read().decode())

def release(state):
    d=req("POST", f"/projects/{proj}/process-definition/{wf}/release", {"releaseState": state}, form=True)
    print("release", state, d.get("code"), d.get("msg"))
    if d.get("code")!=0:
